        while (!ct.IsCancellationRequested)
        {
            await using (var db = await factory.CreateDbContextAsync(ct))   // one unit of work per iteration
            {
                var batch = await db.Outbox.Where(m => m.SentAt == null)
                                           .OrderBy(m => m.Id).Take(100).ToListAsync(ct);
